import{_ as r,o as t,c as o,a6 as e}from"./chunks/framework.CGCCzANv.js";const c=JSON.parse('{"title":"MOTHER 1（地球冒险1）正统完整剧情","description":"","frontmatter":{"readingTime":"13 min read"},"headers":[],"relativePath":"游戏引擎/游戏设计/系列游戏/MOTHER/MOTHER1.md","filePath":"游戏引擎/游戏设计/系列游戏/MOTHER/MOTHER1.md"}'),n={name:"游戏引擎/游戏设计/系列游戏/MOTHER/MOTHER1.md"};function s(p,a,i,h,l,d){return t(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="mother-1-地球冒险1-正统完整剧情" tabindex="-1">MOTHER 1（地球冒险1）正统完整剧情 <a class="header-anchor" href="#mother-1-地球冒险1-正统完整剧情" aria-label="Permalink to &quot;MOTHER 1（地球冒险1）正统完整剧情&quot;">​</a></h1><h2 id="世界观基础-原作设定" tabindex="-1">世界观基础（原作设定） <a class="header-anchor" href="#世界观基础-原作设定" aria-label="Permalink to &quot;世界观基础（原作设定）&quot;">​</a></h2><p>数十年前，主角的曾祖父<strong>乔治（George）</strong>、曾祖母**玛丽亚（Maria）<strong>被外星文明掳走。乔治偷学外星PSI超能力，独自逃回地球；玛丽亚被遗落在外星，抚养外星幼体</strong>基格（Giegue）**长大，并时常哼唱专属摇篮曲。多年后，基格因复杂的依恋与被抛弃的怨恨，向地球发动复仇，引发现世全域异象：民众失控发狂、死者化为僵尸、动物狂暴畸变、PSI能量泛滥，世界秩序彻底崩坏。</p><p>魔术城<strong>Magicant</strong>并非实体世界，是玛丽亚残留的精神幻境，承载着她遗失的记忆与对基格的执念。贯穿全篇的<strong>八段旋律</strong>，正是当年玛丽亚安抚基格的摇篮曲碎片，是拯救世界、化解恩怨的唯一核心。</p><h2 id="第一章-家园异变-少年启程" tabindex="-1">第一章 家园异变，少年启程 <a class="header-anchor" href="#第一章-家园异变-少年启程" aria-label="Permalink to &quot;第一章 家园异变，少年启程&quot;">​</a></h2><p>某日深夜，主角尼特（Ninten）的家中突发剧烈地震，屋内家具、物品全部失控暴走，世界异变正式降临。主角击退初期暴走物件，在房间找到曾祖父乔治遗留的日记，首次得知PSI超能力、外星绑架事件的隐秘过往。</p><p>与家人对话后，主角了解到小镇周边频发的诡异异象：路人无故发狂、野外出现诡异怪物。通过简单的居家解密，找到储藏室钥匙，获取基础武器、道具与补给，完成基础战斗与探索练习，正式离开家乡外出冒险。</p><p>途经梅里维尔镇（Merrysville），一对夫妇焦急托付主角：他们的女儿安娜（Ana）独自外出后失踪，杳无音讯。二人恳请主角若进入城镇，务必将此事告知市长，寻求官方协助寻人。</p><h2 id="第二章-小镇传闻-金丝雀之谜" tabindex="-1">第二章 小镇传闻，金丝雀之谜 <a class="header-anchor" href="#第二章-小镇传闻-金丝雀之谜" aria-label="Permalink to &quot;第二章 小镇传闻，金丝雀之谜&quot;">​</a></h2><p>主角进入梅里维尔镇，听闻城内郊外墓地频繁出现僵尸游荡，人心惶惶。主角拜访市长，市长确认了少女失踪的事态，委托主角尽力搜寻安娜的下落。</p><p>前往城镇商店打探线索后，主角获得一只幼年金丝雀。前往郊外墓地，通过破解墓碑排列、碑文对应的机关解密，开启墓地隐藏地下暗门。暗门深处栖息着金丝雀母体，主角将幼鸟归还母鸟，完成羁绊共鸣，获得<strong>第一段旋律碎片</strong>。</p><p>主角继续深入地下洞穴地宫，清理游荡的僵尸与畸变怪物，最终成功找到并救下失踪的安娜。安娜拥有天生的治愈系PSI能力，自此加入队伍，成为首位同伴。</p><h2 id="第三章-异界开启-魔术城的委托" tabindex="-1">第三章 异界开启，魔术城的委托 <a class="header-anchor" href="#第三章-异界开启-魔术城的委托" aria-label="Permalink to &quot;第三章 异界开启，魔术城的委托&quot;">​</a></h2><p>为探寻更多异变真相与旋律碎片，主角一行人深入大陆隐秘洞窟。洞窟深处留存着远古PSI传送装置，触碰装置后，主角脱离现实世界，进入玛丽亚的精神幻境——<strong>魔术城（Magicant）</strong>。</p><p>魔术城由记忆与执念构筑，场景唯美却暗藏死寂。主角抵达皇城，觐见魔术城统治者<strong>玛丽女王（Queen Mary）</strong>。女王早已遗失过往记忆，只剩模糊的执念，她告知主角：散落世间的<strong>八段旋律</strong>是唤醒她记忆、平息世间灾厄的关键，委托主角收集全部旋律碎片。</p><p>进入魔术城专属迷宫，迷宫机关繁复、魔物众多。迷宫最深处栖息着实力远超当前玩家的<strong>远古巨龙</strong>，属于可选隐藏BOSS，玩家可规避战斗、安全绕行。若成功击败巨龙，可获取对应旋律碎片与高阶道具，同时解锁全域传送道具，实现自由穿梭各地城镇。</p><h2 id="第四章-少年小镇-第二位同伴归队" tabindex="-1">第四章 少年小镇，第二位同伴归队 <a class="header-anchor" href="#第四章-少年小镇-第二位同伴归队" aria-label="Permalink to &quot;第四章 少年小镇，第二位同伴归队&quot;">​</a></h2><p>借助传送能力，主角抵达少年镇。此地因异变风气混乱，弱小的少年劳埃德（Lloyd）长期被同龄人欺凌，性格怯懦却精通机械与枪械。</p><p>主角帮助劳埃德找回被抢夺的专属道具、解围脱困，劳埃德感念帮助，决心跟随主角冒险，凭借精准的远程枪械战力，成为队伍<strong>第二位同伴</strong>。</p><h2 id="第五章-全域巡游-收集散落旋律" tabindex="-1">第五章 全域巡游，收集散落旋律 <a class="header-anchor" href="#第五章-全域巡游-收集散落旋律" aria-label="Permalink to &quot;第五章 全域巡游，收集散落旋律&quot;">​</a></h2><p>队伍开启跨区域探索，遍历各地异变城镇，逐一回收旋律碎片：</p><p>前往<strong>幽灵城</strong>，整座城镇被幽冥怨念笼罩，亡灵怪物遍地游荡。主角清理亡灵魔物、破解幽灵记忆谜题，解锁城镇隐藏秘宝，获取新的旋律碎片。</p><p>穿越酷热荒漠，抵达<strong>沙漠镇</strong>，沙漠生物尽数畸变狂暴，流沙与风暴陷阱遍布。突破荒漠险境、击败精英畸变怪物后，获得第五段旋律碎片。</p><p>重返少年镇完成PSI专属试炼，主角解锁全新高阶精神技能，战力大幅提升。随后穿过瘴气弥漫的死亡沼泽，抵达被黑帮完全掌控的<strong>帮会市</strong>。</p><p>帮会市因彻底失控的秩序与异变乱象，沦为暴力之城。当地强势的格斗强者泰迪（Teddy）痛恨黑帮恶行与世间乱象，被主角的正义信念打动，舍弃黑道身份，加入队伍成为<strong>第三位、最终同伴</strong>，队伍正式成型。</p><h2 id="第六章-再战巨龙-旋律补全" tabindex="-1">第六章 再战巨龙，旋律补全 <a class="header-anchor" href="#第六章-再战巨龙-旋律补全" aria-label="Permalink to &quot;第六章 再战巨龙，旋律补全&quot;">​</a></h2><p>伴随着队伍全员成长、技能与装备成型，主角重返魔术城迷宫，主动挑战远古巨龙。经过高强度激战，成功击败这一隐藏BOSS，获取<strong>第六段旋律碎片</strong>，八段旋律仅剩最后两段。</p><h2 id="第七章-山地真相-机器人的守护与落幕" tabindex="-1">第七章 山地真相，机器人的守护与落幕 <a class="header-anchor" href="#第七章-山地真相-机器人的守护与落幕" aria-label="Permalink to &quot;第七章 山地真相，机器人的守护与落幕&quot;">​</a></h2><p>队伍翻越群山，抵达异变能量最浓郁的糸井山区域。此地空间裂隙频发，大量外星异形生物入侵现世，是基格的前置守卫势力。一路清理外星魔物后，主角一行人抵达山间小屋，短暂休整，伙伴间羁绊深化。</p><p>休憩之际，高阶外星战斗机器人突然突袭，战力碾压全队，触发剧情绝境，队伍全员重伤。危急时刻，曾祖父乔治打造的专属守护机器人<strong>EVE</strong>现身，拦下强敌救下众人。</p><p>队伍休养痊愈后，循着空间异象线索，穿过湖心漩涡，进入深山隐藏的水下秘密基地。EVE在此等候多年，向主角揭示自身身份：它是乔治遗留的守护造物，毕生使命便是保护主角、阻拦外星势力。</p><p>紧随而至的外星BOSS机器人发起死战，EVE为完成使命，全力迎战，最终与敌机器人能量过载、同归于尽。主角在EVE的残骸核心中，找到<strong>第七段旋律碎片</strong>。</p><h2 id="第八章-宿命揭秘-过往的真相" tabindex="-1">第八章 宿命揭秘，过往的真相 <a class="header-anchor" href="#第八章-宿命揭秘-过往的真相" aria-label="Permalink to &quot;第八章 宿命揭秘，过往的真相&quot;">​</a></h2><p>主角登顶雪山禁地，找到曾祖父乔治的尘封墓碑与遗留录音、手记。最终的真相彻底揭晓：</p><p>魔术城的玛丽女王，正是主角的曾祖母<strong>玛丽亚</strong>。八段摇篮曲旋律，是她当年在外星抚养幼年期基格时，日日哼唱的歌谣。乔治盗取外星PSI能力独自逃离，将玛丽亚永远留在外星，也为后世的地球灾厄埋下祸根。</p><p>在乔治墓碑的隐秘处，主角找到<strong>最后一段旋律碎片</strong>，自此<strong>八段宿命旋律全部集齐</strong>。</p><h2 id="第九章-幻境终焉-恩怨溯源" tabindex="-1">第九章 幻境终焉，恩怨溯源 <a class="header-anchor" href="#第九章-幻境终焉-恩怨溯源" aria-label="Permalink to &quot;第九章 幻境终焉，恩怨溯源&quot;">​</a></h2><p>主角携完整旋律重返魔术城皇宫，在祭坛之上奏响完整摇篮曲。神圣的旋律席卷整片精神幻境，玛丽女王被尘封的百年记忆彻底苏醒。</p><p>她忆起自己的一生、遗弃的遗憾、对基格的温柔与愧疚，所有执念尽数消解。完成毕生执念的玛丽亚彻底消散，依托她精神存在的魔术城幻境，也随之彻底崩塌、归于虚无，主角被传送回现实世界的山顶。</p><h2 id="第十章-终局之战-温柔的救赎" tabindex="-1">第十章 终局之战，温柔的救赎 <a class="header-anchor" href="#第十章-终局之战-温柔的救赎" aria-label="Permalink to &quot;第十章 终局之战，温柔的救赎&quot;">​</a></h2><p>幻境消散后，最后的屏障褪去，终极外星BOSS**基格（Giegue）**降临山顶，直面主角。</p><p>基格诉说复仇的根源：幼时被玛丽亚温柔抚养，拥有最纯粹的美好记忆，却因乔治的背叛、玛丽亚的遗弃，一生被困在爱恨矛盾中。他痛恨人类的自私与背叛，因此跨越星际归来，意图毁灭地球宣泄怨恨。</p><p>本作终战无杀戮与征服，主角全程反复奏响八段摇篮曲，用熟悉的旋律唤醒基格心底仅存的温柔童年记忆。</p><p>在旋律的治愈下，基格彻底瓦解了复仇的执念，放下百年怨恨。他没有伤害主角，也没有毁灭地球，最终转身离去，消失在星际深处，全域异变彻底终止。</p><h2 id="终章-全员归宿-原作正统结局" tabindex="-1">终章 全员归宿（原作正统结局） <a class="header-anchor" href="#终章-全员归宿-原作正统结局" aria-label="Permalink to &quot;终章 全员归宿（原作正统结局）&quot;">​</a></h2><p><strong>尼特（主角）</strong>：结束所有宿命冒险，回归家乡小镇，与家人团聚，守护重归安宁的世界。</p><p><strong>安娜</strong>：回到梅里维尔镇，留在故乡，以PSI治愈能力守护小镇居民，守护一方安稳。</p><p><strong>劳埃德</strong>：重返校园，潜心钻研机械与科学技术，褪去怯懦，成长为可靠的少年研究者。</p><p><strong>泰迪</strong>：回归帮会市，彻底肃清城市黑帮乱象，终结暴力统治，重建城镇秩序与和平。</p><p>世间所有异象消散，魔物、丧尸、畸变生物尽数消失，被破坏的世界逐步复苏，百年宿命恩怨彻底落幕。</p><blockquote><p>（注：部分内容可能由 AI 生成）</p></blockquote>',51)])])}const u=r(n,[["render",s]]);export{c as __pageData,u as default};
